configuration.tbelDecoder:
// Parsing sicuro del payload
var rawData = decodeToJson(payload);
var p = rawData.payload || rawData;

var hw = p.hw || {};
var analysis = p.analysis || {};

// Assegnazione delle sole metriche necessarie alla dashboard Sentinel
return {
   deviceName: p.device_id || "sensore_001",
   deviceType: 'Optical Biosensor',
   telemetry: {
       // Biosensor Data
       spore_count: analysis.spore_count || 0,
       detected: analysis.detected ? 1 : 0,
       frame_id: p.frame_id,
       sample_id: p.sample_id,
       
       // Hardware Diagnostics
       cpu_temp_c: hw.cpu_temp_c,
       processing_time_s: hw.processing_time_s,
       ram_used_percent: hw.ram ? hw.ram.used_percent : null,
       disk_used_percent: hw.disk ? hw.disk.used_percent : null
   }
};
